<script lang="ts">
	import { onMount } from 'svelte'; import { allBookings, deleteBooking, updateBookingStatus } from '$lib/api/bookings'; import type { Booking, BookingStatus } from '$lib/api/types'; import BookingTable from '$lib/components/BookingTable.svelte'; import Card from '$lib/components/ui/Card.svelte'; import Alert from '$lib/components/ui/Alert.svelte';
	let bookings = $state<Booking[]>([]); let loading = $state(true); let error = $state(''); async function load() { loading = true; try { bookings = (await allBookings()).content; } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not load bookings.'; } finally { loading = false; } } onMount(load);
	async function changeStatus(id: number, status: BookingStatus) { try { await updateBookingStatus(id, status); await load(); } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not update booking.'; } } async function remove(id: number) { if (!confirm('Delete this booking?')) return; try { await deleteBooking(id); await load(); } catch (reason) { error = reason instanceof Error ? reason.message : 'Could not delete booking.'; } }
</script>
<div class="space-y-5"><div><h1 class="text-2xl font-semibold">Bookings</h1><p class="text-sm text-slate-600">Update a booking status or delete a booking.</p></div>{#if error}<Alert>{error}</Alert>{/if}<Card>{#if loading}<p class="text-sm text-slate-500">Loading bookings…</p>{:else if bookings.length === 0}<p class="text-sm text-slate-500">No bookings found.</p>{:else}<BookingTable {bookings} admin onStatus={changeStatus} /><div class="mt-4 flex flex-wrap gap-2">{#each bookings as booking}<button class="text-xs text-red-700 underline" onclick={() => remove(booking.id)}>Delete #{booking.id}</button>{/each}</div>{/if}</Card></div>
